    <script>
        // Game Configuration
        const GRID_SIZE = 30;
        const CELL_SIZE = 20; // 900 / 30 = 30... wait, let me recalculate
        const CANVAS_SIZE = 900;
        const INITIAL_SPEED = 150; // milliseconds per move
        const SPEED_INCREMENT = 5; // how much to speed up each 10 points

        // Colors
        const COLORS = {
            snake1Head: '#e94560',
            snake1Body: '#ff6b8a',
            snake2Head: '#4ecdc4',
            snake2Body: '#6ccebd',
            food: '#f1c40f',
            grid: '#2c3e50'
        };

        // Game State
        let canvas, ctx;
        let score1 = 0;
        let score2 = 0;
        let highScore = 0;
        let gameLoop = null;
        let isPaused = false;
        let gameActive = false;
        let currentMode = 'human-vs-human';

        // Snake objects
        let snake1 = {
            x: 15,
            y: 15,
