            dx: -1,
            dy: 0,
            tail: []
        };

        // Food position
        let food = {
            x: 0,
            y: 0
        };

        // Initialize the canvas
        function initCanvas() {
            canvas = document.getElementById('gameCanvas');
            ctx = canvas.getContext('2d');
            resetGame();
        }

        // Reset game state
        function resetGame() {
            score1 = 0;
            score2 = 0;
            updateScoreDisplay();

            // Reset snakes - position them apart
            snake1 = {
                x: 15,
                y: 15,
                dx: 1,
                dy: 0,
                tail: []
