            spawnFood();

            gameActive = true;
            isPaused = false;
            showMenu(false);
            gameLoop = setInterval(updateGame, INITIAL_SPEED);
        }

        // Spawn food at random position not occupied by snakes
        function spawnFood() {
            let validPosition = false;
            while (!validPosition) {
                food.x = Math.floor(Math.random() * GRID_SIZE);
                food.y = Math.floor(Math.random() * GRID_SIZE);

                validPosition = true;

                // Check if food is on snake1
                if (food.x === snake1.x && food.y === snake1.y) {
                    validPosition = false;
                    continue;
                }

                // Check if food is on snake2
                if (food.x === snake2.x && food.y === snake2.y) {
                    validPosition = false;
                    continue;
                }

                // Check if food is on snake tails
                for (let i = 0; i < snake1.tail.length; i++) {
                    if (food.x === snake1.tail[i].x && food.y === snake1.tail[i].y) {
                        validPosition = false;
                        break;
                    }
                }

                if (!validPosition) continue;

                for (let i = 0; i < snake2.tail.length; i++) {
                    if (food.x === snake2.tail[i].x && food.y === snake2.tail[i].y) {
                        validPosition = false;
                        break;
                    }
                }
            }
        }

        // Update score display
        function updateScoreDisplay() {
            document.getElementById('scoreDisplay').innerHTML = 
                'Score: <span>' + score1 + '</span> - <span>' + score2 + '</span>';
        }

        // Draw a single cell
        function drawCell(x, y, color, isHead = false) {
            ctx.fillStyle = color;
            ctx.fillRect(x * CELL_SIZE, y * CELL_SIZE, CELL_SIZE - 2, CELL_SIZE - 2);

            // Draw eye on head if desired
            if (isHead) {
                ctx.fillStyle = '#fff';
                const eyeSize = 3;
                if (isHead === 'snake1') {
                    ctx.fillRect(x * CELL_SIZE + 5, y * CELL_SIZE + 5, eyeSize, eyeSize);
                    ctx.fillRect(x * CELL_SIZE + CELL_SIZE - 8, y * CELL_SIZE + 5, eyeSize, eyeSize);
                } else if (isHead === 'snake2') {
                    ctx.fillRect(x * CELL_SIZE + 5, y * CELL_SIZE + CELL_SIZE - 8, eyeSize, eyeSize);
                    ctx.fillRect(x * CELL_SIZE + CELL_SIZE - 8, y * CELL_SIZE + CELL_SIZE - 8, eyeSize, eyeSize);
                }
            }
        }

        // Draw snakes
        function drawSnakes() {
            // Draw snake1 tail
            for (let i = 0; i < snake1.tail.length; i++) {
                const isHead = (i === snake1.tail.length - 1);
                drawCell(snake1.tail[i].x, snake1.tail[i].y, 
                    isHead ? COLORS.snake1Head : COLORS.snake1Body,
                    isHead ? 'snake1' : null);
            }
            // Draw snake1 head
            drawCell(snake1.x, snake1.y, COLORS.snake1Head, true);

            // Draw snake2 tail
            for (let i = 0; i < snake2.tail.length; i++) {
                const isHead = (i === snake2.tail.length - 1);
                drawCell(snake2.tail[i].x, snake2.tail[i].y,
                    isHead ? COLORS.snake2Head : COLORS.snake2Body,
                    isHead ? 'snake2' : null);
            }
            // Draw snake2 head
            drawCell(snake2.x, snake2.y, COLORS.snake2Head, true);
        }

        // Draw food
        function drawFood() {
            // Draw apple
            ctx.fillStyle = COLORS.food;
            ctx.beginPath();
            ctx.foodX = food.x * CELL_SIZE + CELL_SIZE / 2;
            ctx.foodY = food.y * CELL_SIZE + CELL_SIZE / 2;
            ctx.foodRadius = CELL_SIZE / 2 - 4;
            ctx.foodX = food.x * CELL_SIZE + 4;
            ctx.foodY = food.y * CELL_SIZE + 4;
            ctx.fillRect(food.x * CELL_SIZE + 4, food.y * CELL_SIZE + 4, CELL_SIZE - 8, CELL_SIZE - 8);

            // Draw leaf
            ctx.fillStyle = '#27ae60';
            ctx.beginPath();
            ctx.moveTo(food.x * CELL_SIZE + CELL_SIZE / 2, food.y * CELL_SIZE + 2);
            ctx.lineTo(food.x * CELL_SIZE + CELL_SIZE - 2, food.y * CELL_SIZE + CELL_SIZE - 2);
            ctx.lineTo(food.x * CELL_SIZE + 2, food.y * CELL_SIZE + CELL_SIZE - 2);
            ctx.closePath();
            ctx.fill();
        }

        // Draw grid
        function drawGrid() {
            ctx.strokeStyle = COLORS.grid;
            ctx.lineWidth = 1;

            for (let i = 0; i <= GRID_SIZE; i++) {
                // Vertical lines
                ctx.beginPath();
                ctx.moveTo(i * CELL_SIZE, 0);
                ctx.lineTo(i * CELL_SIZE, CANVAS_SIZE);
                ctx.stroke();

                // Horizontal lines
                ctx.beginPath();
                ctx.moveTo(0, i * CELL_SIZE);
                ctx.lineTo(CANVAS_SIZE, i * CELL_SIZE);
                ctx.stroke();
            }
        }

        // Update game state
        function updateGame() {
            if (!gameActive || isPaused) return;

            // Move snake1
            const newHead1 = { x: snake1.x + snake1.dx, y: snake1.y + snake1.dy };

            // Check wall collision for snake1
            if (newHead1.x < 0 || newHead1.x >= GRID_SIZE || newHead1.y < 0 || newHead1.y >= GRID_SIZE) {
                gameOver();
                return;
            }

            // Check self collision for snake1
            for (let i = 0; i < snake1.tail.length; i++) {
                if (newHead1.x === snake1.tail[i].x && newHead1.y === snake1.tail[i].y) {
                    gameOver();
                    return;
                }
            }

            // Move snake1
            snake1.tail.unshift({ x: snake1.x, y: snake1.y });
            snake1.x = newHead1.x;
            snake1.y = newHead1.y;

            // Check food collision for snake1
            if (snake1.x === food.x && snake1.y === food.y) {
                score1++;
                // Speed up game every 10 points
                if (score1 % 10 === 0 && INITIAL_SPEED - (score1 / 10) * SPEED_INCREMENT > 50) {
                    clearInterval(gameLoop);
                    gameLoop = setInterval(updateGame, INITIAL_SPEED - (score1 / 10) * SPEED_INCREMENT);
                }
                spawnFood();
            } else {
                snake1.tail.pop();
            }

            // Move snake2 - depends on mode
            if (currentMode === 'human-vs-human') {
                // Snake2 follows keyboard controls
                const newHead2 = { x: snake2.x + snake2.dx, y: snake2.y + snake2.dy };

                // Check wall collision for snake2
                if (newHead2.x < 0 || newHead2.x >= GRID_SIZE || newHead2.y < 0 || newHead2.y >= GRID_SIZE) {
                    gameOver();
                    return;
                }

                // Check self collision for snake2
                for (let i = 0; i < snake2.tail.length; i++) {
                    if (newHead2.x === snake2.tail[i].x && newHead2.y === snake2.tail[i].y) {
                        gameOver();
                        return;
                    }
                }

                // Move snake2
                snake2.tail.unshift({ x: snake2.x, y: snake2.y });
                snake2.x = newHead2.x;
                snake2.y = newHead2.y;

                // Check food collision for snake2
                if (snake2.x === food.x && snake2.y === food.y) {
                    score2++;
                    if (score2 % 10 === 0 && INITIAL_SPEED - (score2 / 10) * SPEED_INCREMENT > 50) {
                        clearInterval(gameLoop);
                        gameLoop = setInterval(updateGame, INITIAL_SPEED - (score2 / 10) * SPEED_INCREMENT);
                    }
                    spawnFood();
                } else {
                    snake2.tail.pop();
                }
            } else if (currentMode === 'cpu-vs-human') {
                // Snake2 is CPU - follow food
                moveCpuSnake(snake2, snake1, isSnake2Cpu = true);

                // Check food collision for snake2
                if (snake2.x === food.x && snake2.y === food.y) {
                    score2++;
                    if (score2 % 10 === 0 && INITIAL_SPEED - (score2 / 10) * SPEED_INCREMENT > 50) {
                        clearInterval(gameLoop);
                        gameLoop = setInterval(updateGame, INITIAL_SPEED - (score2 / 10) * SPEED_INCREMENT);
                    }
                    spawnFood();
                } else {
                    // Move snake2 tail
                    if (snake2.tail.length > 0) {
                        snake2.tail.pop();
                    }
                }
            } else if (currentMode === 'cpu-vs-cpu') {
                // Both are CPU - move snake2 toward food
                moveCpuSnake(snake2, snake1, isSnake2Cpu = true);

                // Check food collision for snake2
                if (snake2.x === food.x && snake2.y === food.y) {
                    score2++;
                    if (score2 % 10 === 0 && INITIAL_SPEED - (score2 / 10) * SPEED_INCREMENT > 50) {
                        clearInterval(gameLoop);
                        gameLoop = setInterval(updateGame, INITIAL_SPEED - (score2 / 10) * SPEED_INCREMENT);
                    }
                    spawnFood();
                } else {
                    // Move snake2 tail
                    if (snake2.tail.length > 0) {
                        snake2.tail.pop();
                    }
                }
