            if (currentMode === 'human-vs-human' || currentMode === 'cpu-vs-human') {
                for (let i = 0; i < snake2.tail.length; i++) {
                    if (snake1.x === snake2.tail[i].x && snake1.y === snake2.tail[i].y) {
                        gameOver();
                        return;
                    }
                }
            }

            // Draw everything
            ctx.clearRect(0, 0, CANVAS_SIZE, CANVAS_SIZE);
            drawGrid();
            drawFood();
            drawSnakes();
            updateScoreDisplay();
        }

        // CPU snake movement - chase food
        function moveCpuSnake(snake, otherSnake, isSnakeCpu) {
            const targetX = food.x;
            const targetY = food.y;

            // Determine direction toward food
            let newDx = snake.dx;
            let newDy = snake.dy;

            // Calculate direction
            if (snake.x < targetX) newDx = 1;
            else if (snake.x > targetX) newDx = -1;
            else if (snake.y < targetY) newDy = 1;
            else if (snake.y > targetY) newDy = -1;

            // Check if new direction would cause collision with wall
            const testX = snake.x + newDx;
            const testY = snake.y + newDy;

            if (testX >= 0 && testX < GRID_SIZE && testY >= 0 && testY < GRID_SIZE) {
                // Check self collision
                let collision = false;
                for (let i = 0; i < snake.tail.length; i++) {
                    if (testX === snake.tail[i].x && testY === snake.tail[i].y) {
                        collision = true;
                        break;
                    }
                }

                // Check other snake collision (only in human-vs-cpu)
                if (!collision && isSnakeCpu && currentMode === 'cpu-vs-human') {
                    for (let i = 0; i < otherSnake.tail.length; i++) {
                        if (testX === otherSnake.tail[i].x && testY === otherSnake.tail[i].y) {
                            collision = true;
                            break;
                        }
                    }
                }

                if (!collision) {
                    snake.dx = newDx;
                    snake.dy = newDy;
                }
            }
        }

        // Game over
        function gameOver() {
            clearInterval(gameLoop);
            gameActive = false;
            isPaused = false;

            if (score1 > highScore) {
                highScore = score1;
            }

            document.getElementById('gameOverScore').innerHTML = 
                'Final Score: Player 1: ' + score1 + ' | Player 2: ' + score2;
            showMenu(true);
        }

        // Show/hide menu
        function showMenu(show) {
            const startMenu = document.getElementById('startMenu');
            const gameOverScreen = document.getElementById('gameOverScreen');
            const gameContainer = document.getElementById('gameContainer');
            const modeSelect = document.getElementById('modeSelect');

            if (show) {
                startMenu.style.display = 'none';
                gameOverScreen.classList.add('visible');
                gameContainer.style.display = 'none';
                modeSelect.classList.add('visible');
            } else {
                startMenu.style.display = 'none';
                gameOverScreen.classList.remove('visible');
                gameContainer.style.display = 'flex';
                modeSelect.classList.remove('visible');
            }
        }

        // Handle keyboard controls
        document.addEventListener('keydown', (e) => {
            // Don't handle if menu or game over is visible
            const startMenu = document.getElementById('startMenu');
            const gameOverScreen = document.getElementById('gameOverScreen');
            const modeSelect = document.getElementById('modeSelect');

            if (startMenu.style.display !== 'none' || gameOverScreen.classList.contains('visible') || modeSelect.classList.contains('visible')) {
                // Handle menu navigation
                if (e.key === 'Enter' || e.key === ' ') {
                    if (startMenu.style.display !== 'none') {
                        // Start game
                        const modeBtn = document.querySelector('.mode-btn.selected');
                        if (modeBtn) {
                            currentMode = modeBtn.dataset.mode;
                            hideStartMenu();
                        }
                    } else if (gameOverScreen.classList.contains('visible')) {
                        restartGame();
                    } else if (modeSelect.classList.contains('visible')) {
                        const modeBtn = document.querySelector('.mode-option.selected');
                        if (modeBtn) {
                            currentMode = modeBtn.classList.contains('human-vs-human') ? 'human-vs-human' :
                                        modeBtn.classList.contains('cpu-vs-human') ? 'cpu-vs-human' : 'cpu-vs-cpu';
                            hideModeSelect();
                        }
                    }
                }
                // Select mode
                if (e.key === 'ArrowDown' || e.key === 's') {
                    const options = document.querySelectorAll('.mode-option, .mode-btn');
                    const current = document.querySelector('.mode-option.selected, .mode-btn.selected');
                    if (!current) {
                        // First selection - pick first option
                        options[0].classList.add('selected');
                    } else {
                        const currentIdx = Array.from(options).indexOf(current);
                        const nextIdx = (currentIdx + 1) % options.length;
                        options[currentIdx].classList.remove('selected');
                        options[nextIdx].classList.add('selected');
                    }
                }
                if (e.key === 'ArrowUp' || e.key === 'w') {
                    const options = document.querySelectorAll('.mode-option, .mode-btn');
                    const current = document.querySelector('.mode-option.selected, .mode-btn.selected');
                    if (!current) {
                        options[0].classList.add('selected');
                    } else {
                        const currentIdx = Array.from(options).indexOf(current);
                        const prevIdx = (currentIdx - 1 + options.length) % options.length;
                        options[currentIdx].classList.remove('selected');
                        options[prevIdx].classList.add('selected');
                    }
                }
                return;
            }

            // Game controls
            if (e.key === 'p' || e.key === 'P') {
                isPaused = !isPaused;
            }

            if (e.key === 'r' || e.key === 'R') {
                restartGame();
                return;
            }

            // Player 1 controls (WASD)
            if (currentMode === 'human-vs-human' || currentMode === 'cpu-vs-human') {
                if (e.key === 'w' && snake1.dy !== 1) { snake1.dy = -1; snake1.dx = 0; }
                if (e.key === 's' && snake1.dy !== -1) { snake1.dy = 1; snake1.dx = 0; }
                if (e.key === 'a' && snake1.dx !== 1) { snake1.dx = -1; snake1.dy = 0; }
                if (e.key === 'd' && snake1.dx !== -1) { snake1.dx = 1; snake1.dy = 0; }
                if (e.key === 'ArrowUp' && snake1.dy !== 1) { snake1.dy = -1; snake1.dx = 0; }
                if (e.key === 'ArrowDown' && snake1.dy !== -1) { snake1.dy = 1; snake1.dx = 0; }
                if (e.key === 'ArrowLeft' && snake1.dx !== 1) { snake1.dx = -1; snake1.dy = 0; }
                if (e.key === 'ArrowRight' && snake1.dx !== -1) { snake1.dx = 1; snake1.dy = 0; }
